/**
 * Runs a query against the denormalised index.
 *
 * `advanced_search` is the only thing that turns `kind:` / `in:` / `project:`
 * into filters. Without it the whole string is a literal substring and only
 * issues are returned, whatever kinds the caller asked for. A colon is never
 * a reason to refuse the query.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  const parsed = parseSearchQuery(input.q, advanced);
  // Without the flag every typed character is literal, including spaces.
  // With it, the shared parser decides the free text and any field tokens.
  const text = advanced ? parsed.text : input.q;
  const kinds: SearchQueryInput["kinds"] = !advanced
    ? ["issue"]
    : parsed.kindsFromQuery
      ? [...parsed.kinds]
      : [...input.kinds];
  const searched: SearchQueryInput = { ...input, q: text, kinds };
  if (advanced && parsed.projectId !== null) {
    searched.projectId = parsed.projectId;
  }

  const page = await searchRepo.searchDocuments(searched);

