export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  // A comment belongs to its issue's project, including when that issue is
  // archived — the id is what `project:` and `projectId` filter on.
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue?.projectId ?? null,
  );
}

