/**
 * Writes one subject back into the index, or removes it when the row is gone
 * or archived. Used by explicit reindex requests and by project restore.
 */
async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  if (subjectKind === "issue") {
    const issue = await issueRepo.findIssueById(orgId, subjectId as Issue["id"]);
    if (issue && isLive(issue)) await indexIssue(orgId, issue);
    else await removeFromIndex(orgId, "issue", subjectId);
    return;
  }

  if (subjectKind === "comment") {
    const comment = await commentRepo.findCommentById(
      orgId,
      subjectId as Comment["id"],
    );
    if (comment && isLive(comment)) await indexComment(orgId, comment);
    else await removeFromIndex(orgId, "comment", subjectId);
    return;
  }

  const project = await projectRepo.findProjectById(
    orgId,
    subjectId as Project["id"],
  );
  if (project && isLive(project)) await indexProject(orgId, project);
  else await removeFromIndex(orgId, "project", subjectId);
}

